export async function deepenLessons() {
  for (const [topicId, sections] of Object.entries(additions)) {
    const filename = `apps/showcase/src/content/lessons/${topicId}.json`;
    const lesson = JSON.parse(await fs.readFile(filename, "utf8"));
    const addedIds = new Set(["learning-route", ...sections.map((section) => section.id)]);
    lesson.sections = lesson.sections.filter((section) => !addedIds.has(section.id));
    lesson.sections.unshift(s("learning-route", "Как изучать эту главу", p("Начните с основных понятий, затем пройдите подробные параграфы. В каждом разобранном примере найдите признак правила и объясните, почему контрпример ему не соответствует. Ответьте на вопросы проверки без раскрытия пояснений. После этого решите задания соответствующей линии ОГЭ; при ошибке вернитесь к конкретному параграфу. Краткий итог служит памяткой после изучения, а не заменяет разбор.")));
    lesson.sections.push(...sections);
    const cases = lesson.sections.flatMap((section) => section.blocks).find((block) => block.type === "interactive" && block.data.kind === "comparison")?.data.examples;
    if (cases && binaryPatterns[topicId]) {
      for (let n = 0; n < cases.length; n += 1) {
        const item = cases[n];
        const patch = reviewedChoices[topicId]?.[n];
        if (topicId === "sochinenie" && essayEvidence[n]) Object.assign(item, essayEvidence[n]);
        if (patch) { item.options = [...patch.options]; item.expected = [item.options.indexOf(patch.answer) + 1]; }
        const desired = binaryPatterns[topicId][n];
        if (desired && item.options.length === 2 && item.expected[0] !== desired) {
          item.options.reverse();
          item.expected = [3 - item.expected[0]];
          if (item.optionExplanations) item.optionExplanations.reverse();
        }
        item.explanation = item.explanation.replace("Первый вариант объясняет", "Верный ответ объясняет");
      }
    }
    lesson.revision = Math.max(topicId === "sochinenie" ? 4 : 3, lesson.revision);
    for (const source of lesson.provenance) {
      source.teacherApproval = "pending";
      source.reviewNote = "Объяснения и новые примеры созданы для проекта; выполнена редакционная сверка условий и контрпримеров. Независимая методическая проверка и решение Полины ожидаются.";
      source.reviewedAt = "2026-10-12";
    }
    await fs.writeFile(filename, `${JSON.stringify(lesson, null, 2)}\n`);
  }
  console.log(`Углублены ОГЭ главы: ${Object.keys(additions).length}.`);
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) await deepenLessons();
